package com.fream.back.domain.m16.entity;

import com.fream.back.domain.m02.entity.Xdh20;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.global.entity.Xwb79Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;




@Entity @jakarta.persistence.Table(name = "order_bid")
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xzj27 extends Xwb79Entity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private Xrd81 user;

    @ManyToOne(fetch = FetchType.LAZY)
